import { Directive, Input, OnInit } from '@angular/core';
import { ControlContainer, UntypedFormArray, UntypedFormGroup } from '@angular/forms';
import { EspdControl } from './espd-control';

@Directive({
	selector: '[espdControlName]'
})
export class ControlNameDirective implements OnInit {

	@Input() espdControlName?: string | number;
	control!: EspdControl;

	constructor(private controlContainer: ControlContainer) { }

	ngOnInit(): void {
		if (this.espdControlName !== undefined) {
			const parentGroup = this.controlContainer.control;
			if (parentGroup instanceof UntypedFormGroup) {
				this.control = parentGroup.controls[this.espdControlName] as EspdControl;
			} if (parentGroup instanceof UntypedFormArray && (typeof this.espdControlName === 'number')) {
				this.control = parentGroup.controls[this.espdControlName] as EspdControl;
			}
		}
		if (!this.control) {
			throw new Error(`No control found with name ${this.espdControlName || 'undefined'}`);
		}
	}
}