import { Directive, InjectionToken, Injector, Input, OnChanges, OnInit, SimpleChanges } from '@angular/core';
import { MessageConfig, MessageService } from 'espd-common/i18n';
import { UnsubscribeOnDestroyDirective } from 'espd-common/utils';
import { takeUntil } from 'rxjs/operators';
import { ControlNameDirective } from './control-name.directive';
import { EspdControl } from './espd-control';
import { EspdFormControl } from './form-control';

export const espdAbstractInputComponentInjectionToken = new InjectionToken<EspdAbstractInputDirective>('EspdAbstractInputComponent');

export interface EspdAbstractInputDelegate {
	onInputConfigurationChange: () => void;
}

@Directive()
export abstract class EspdAbstractInputDirective<ControlType extends EspdControl = EspdFormControl> extends UnsubscribeOnDestroyDirective implements OnInit, OnChanges {

	private static nextId: number = 0;

	@Input() public label?: MessageConfig | string;
	@Input() public labelledby: string | null = null;
	@Input() public labelSrOnly: boolean = false;
	@Input() public directions?: MessageConfig | string;
	@Input() public disabled: boolean = false;
	@Input() public required: boolean = false;
	@Input() public hideErrorMessages: boolean = false;
	@Input() public errorMessages!: { [key: string]: string | [string, any] };

	/** An ID to identify this component instance. Used for generating unique IDs in the DOM */
	public id: number;
	public control!: ControlType; //EspdFormControl;

	public messageService: MessageService;

	@Input()
	public set placeholder(value: MessageConfig | string) {
		this.ngUnsubscribe.next();
		this.updatePlaceholder(value);
		this.messageService.onDataUpdate.pipe(takeUntil(this.ngUnsubscribe)).subscribe(() => {
			this.updatePlaceholder(value);
		});
	}

	public get placeholder(): MessageConfig | string {
		return this.placeholderText;
	}

	private placeholderText: string = '';
	private controlNameDirective: ControlNameDirective | null = null;
	private delegates: EspdAbstractInputDelegate[] = [];

	constructor(injector: Injector) {
		super();
		this.id = EspdAbstractInputDirective.nextId++;

		try {
			// eslint-disable-next-line no-bitwise
			this.controlNameDirective = injector.get(ControlNameDirective, undefined, { host: true, optional: true });
		} catch (error) {
			// inject flags are no longer ignored as of angular 12.2.13
			// it would be useful to know if we are getting errors from our use of it
			console.debug("controlNameDirective error: " + error);
		}

		this.messageService = injector.get(MessageService);
	}

	ngOnInit(): void {
		if (this.controlNameDirective) {
			this.control = this.controlNameDirective.control as ControlType;
		}
		if (!this.errorMessages) {
			this.errorMessages = {};
		}
	}

	ngOnChanges(_changes: SimpleChanges): void {
		this.delegates.forEach(delegate => delegate.onInputConfigurationChange());
	}

	/**
	 * Sets browser focus to the form control. It is intended that each form control in this library should provide its own implementation.
	 *
	 * @param target - The target of focus.
	 * `'control'`, which should be designated as the default value, sets focus on the native control to allow for immediate user input.
	 * `'container'` sets the focus to the form control container so screen readers can then read the text of the label, directions, etc.
	 */
	public abstract focus(target: 'control' | 'container'): void;

	public get ariaLabelledby(): string | null {
		if (this.labelledby) {
			return this.labelledby;
		} else {
			return (this.label ? `espd-input-${this.id}` : '') + (this.directions ? ` espd-input-${this.id}-directions` : '') || null;
		}
	}

	public registerDelegate(delegate: EspdAbstractInputDelegate): void {
		this.delegates.push(delegate);
	}

	private updatePlaceholder(value: MessageConfig | string) {
		this.placeholderText = this.messageService.evaluate(value);
	}
}