import { AbstractControl, FormGroup } from '@angular/forms';
import { EspdControl } from './espd-control';
import { clearNestedServerErrors, isAncestorSubmitted, isEspdControl } from './form-utils';

export class EspdFormGroup<TControl extends {
	[K in keyof TControl]: AbstractControl<any>;
} = any> extends FormGroup<TControl> implements EspdControl {

	public serverErrors?: string[] = undefined;
	private _isSubmitted: boolean = false;

	public get hasServerSideErrors(): boolean {
		return this.serverErrorCount > 0;
	}

	public get isSubmitted(): boolean {
		return this._isSubmitted || isAncestorSubmitted(this);
	}

	public set isSubmitted(isSubmitted: boolean) {
		this._isSubmitted = isSubmitted;
	}

	public markAsPristine(): void {
		super.markAsPristine();
		this.isSubmitted = false;
		this.clearServerErrors();
	}

	public reset(value: any = {}, options: { onlySelf?: boolean; emitEvent?: boolean } = {}): void {
		this.clearServerErrors(options?.onlySelf);
		super.reset(value, options);
	}

	public clearServerErrors(onlySelf: boolean = false): void {
		this.serverErrors = undefined;
		if (!onlySelf) {
			// eslint-disable-next-line guard-for-in
			for (const control in this.controls) {
				clearNestedServerErrors(this.controls[control]);
			}
		}
	}

	get showValidationStyles(): boolean {
		return this.showClientValidationMessages;
	}

	get showClientValidationMessages(): boolean {
		return this.invalid && (this.isSubmitted || this.touched);
	}

	public get errorCount(): number {
		const nestedErrors = Object.keys(this.controls)
			.map(k => this.get(k))
			.filter(isEspdControl)
			.map(c => c.errorCount)
			.reduce((previous, current) => previous + current, 0);
		const serverErrors = this.serverErrors ? this.serverErrors.length : 0;
		const frontendErrors = this.errors ? Object.keys(this.errors).length : 0;
		return nestedErrors + serverErrors + frontendErrors;
	}

	public get serverErrorCount(): number {
		const nestedErrors = Object.keys(this.controls)
			.map(k => this.get(k))
			.filter(isEspdControl)
			.map(c => c.serverErrorCount)
			.reduce((previous, current) => previous + current, 0);
		const serverErrors = this.serverErrors ? this.serverErrors.length : 0;
		return nestedErrors + serverErrors;
	}
}