import { Directive, Input, OnInit } from '@angular/core';
import { EspdControl } from './espd-control';
import { EspdFormControl } from './form-control';
import { EspdAbstractInputDirective } from './form-input.component';
import { Sizes } from './form-utils';

@Directive()
export abstract class EspdAbstractSizeableInputDirective<ControlType extends EspdControl = EspdFormControl> extends EspdAbstractInputDirective<ControlType> implements OnInit {

	public width: number = Sizes.lg;

	@Input()
	public set size(value: 'xs' | 'sm' | 'md' | 'lg') {
		this.width = Sizes[value] || Sizes.lg;
	}
	// eslint-disable-next-line @typescript-eslint/explicit-module-boundary-types
	public get size() {
		return Sizes[this.width] as 'xs' | 'sm' | 'md' | 'lg';
	}

	ngOnInit(): void {
		super.ngOnInit();
	}
}