import { AbstractControl, FormArray } from '@angular/forms';
import { EspdControl } from './espd-control';
import { clearNestedServerErrors, isAncestorSubmitted, isEspdControl } from './form-utils';

export class EspdFormArray<TControl extends AbstractControl<any> = any> extends FormArray<TControl> implements EspdControl {
	public serverErrors?: string[] = undefined;

	public reset(value?: any, options?: { onlySelf?: boolean; emitEvent?: boolean }): void {
		this.clearServerErrors(options?.onlySelf);
		super.reset(value, options);
	}

	get showValidationStyles(): boolean {
		return this.showClientValidationMessages || (!!this.serverErrors && this.serverErrors.length > 0);
	}

	get showClientValidationMessages(): boolean {
		return this.invalid && (isAncestorSubmitted(this) || this.touched);
	}

	public clearServerErrors(onlySelf?: boolean): void {
		this.serverErrors = undefined;
		if (!onlySelf) {
			for (const c of this.controls) {
				clearNestedServerErrors(c);
			}
		}
	}

	public get errorCount(): number {
		const nestedErrors = this.controls
			.filter(isEspdControl)
			.map(c => (c as EspdControl).errorCount)
			.reduce((previous, current) => previous + current, 0);
		const serverErrors = this.serverErrors ? this.serverErrors.length : 0;
		const frontendErrors = this.errors ? Object.keys(this.errors).length : 0;
		return nestedErrors + serverErrors + frontendErrors;
	}

	public get serverErrorCount(): number {
		const nestedErrors = this.controls
			.filter(isEspdControl)
			.map(c => (c as EspdControl).serverErrorCount)
			.reduce((previous, current) => previous + current, 0);
		const serverErrors = this.serverErrors ? this.serverErrors.length : 0;
		return nestedErrors + serverErrors;
	}
}