import { AbstractControl, FormArray, FormGroup, UntypedFormArray, UntypedFormGroup } from '@angular/forms';
import { EspdControl } from './espd-control';
import { EspdFormGroup } from './form-group';

export enum Sizes {
	xs = 2,
	sm = 4,
	md = 8,
	lg = 12
}

export const clearNestedServerErrors = (control: AbstractControl): void => {
	if (isEspdControl(control)) {
		control.clearServerErrors(false);
	} else if (control instanceof UntypedFormGroup) {
		for (const c in control.controls) {
			if (Object.prototype.hasOwnProperty.call(control.controls, c)) {
				clearNestedServerErrors(control.controls[c]);
			}
		}
	} else if (control instanceof UntypedFormArray) {
		for (const c of control.controls) {
			clearNestedServerErrors(c);
		}
	}
};

export const isEspdControl = (control: any): control is EspdControl => !!control && Object.prototype.hasOwnProperty.call(control, 'serverErrors');

export const getAllFormValidationErrors = (group: UntypedFormGroup, root: string = ''): any[] => {
	if (root) {
		root = `${root}.`;
	}

	let errors: any[] = getControlErrors(group, root);

	Object.keys(group.controls).forEach(key => {
		const control = group.controls[key];
		errors = errors.concat(getNestedFormValidationErrors(control, `${root}${key}`));
	});
	return errors;
};

export const isAncestorSubmitted = (control: AbstractControl): boolean => {
	let ancestor: FormGroup<any> | FormArray<any> | null = control.parent;
	let isSubmitted = false;
	while (ancestor && !isSubmitted) {
		if (ancestor instanceof EspdFormGroup) {
			isSubmitted = ancestor.isSubmitted;
		}
		ancestor = ancestor.parent;
	}
	return isSubmitted;
};

const getNestedFormValidationErrors = (control: AbstractControl, root: string): any[] => {
	let errors: any[] = getControlErrors(control, root);

	if (control instanceof UntypedFormGroup) {
		Object.keys(control.controls).forEach(key => {
			errors = errors.concat(getNestedFormValidationErrors(control.controls[key], `${root}.${key}`));
		});
	} else if (control instanceof UntypedFormArray) {
		control.controls.forEach((c, i) => {
			errors = errors.concat(getNestedFormValidationErrors(c, `${root}[${i}]`));
		});
	}
	return errors;
};

const getControlErrors = (control: AbstractControl, root: string): any[] => {
	const controlErrors: any = control.errors;
	if (controlErrors !== null) {
		return Object.keys(controlErrors).map(errorKey => ({
			controlName: root,
			errorName: errorKey,
			errorValue: controlErrors[errorKey]
		}));
	} else {
		return [];
	}
};