import { FormControl } from '@angular/forms';
import { EspdControl } from './espd-control';
import { isAncestorSubmitted } from './form-utils';

// The TValue|null is required for compilation to succeed at the moment, but it unfortunately forces all controls to be nullable even if undesireable.
export class EspdFormControl<TValue = any> extends FormControl<TValue | null> implements EspdControl {
	public serverErrors?: string[] = undefined;

	public reset(formState?: any, options?: { onlySelf?: boolean; emitEvent?: boolean }): void {
		this.clearServerErrors();
		super.reset(formState, options);
	}

	get showValidationStyles(): boolean {
		return this.showClientValidationMessages || this.serverErrorCount > 0;
	}

	get showClientValidationMessages(): boolean {
		return !!this.errors && (isAncestorSubmitted(this) || this.touched || this.dirty);
	}

	public clearServerErrors(): void {
		this.serverErrors = undefined;
	}

	public get errorCount(): number {
		let count: number = 0;
		if (this.showValidationStyles) {
			if (this.errors) {
				count += Object.keys(this.errors).length;
			}
			count += this.serverErrorCount;
		}
		return count;
	}

	public get serverErrorCount(): number {
		return this.serverErrors ? this.serverErrors.length : 0;
	}

	get invalid(): boolean {
		return (!!this.errors || !!this.serverErrors) && this.showValidationStyles;
	}
}